W += [
E('symptom','/ˈsɪmptəm/，也可省略 /p/ 音','症状；问题的表现或迹象','表面出现了一些变化，让人注意到背后可能有问题。','希腊 symptoma 接 sympiptein 发生、碰到，来自 syn- 一起 + piptein 落下；经拉丁语和中古英语，后来拼写重新接近古典形式。',SYM,'describe your symptoms 是描述症状；a symptom of poor planning 是规划不足的表现。比喻义不是说计划真的生病，而是用外在表现指向背后的原因。','symptoms of；develop symptoms；a symptom of a wider problem。','医学细分时 symptom 常强调本人感受到的症状，sign 可指观察或检查发现的体征；日常症状一词常用得更宽。原因是 cause，表现是 symptom。',('She described her symptoms clearly during the appointment.','就诊时，她清楚描述了自己的症状。'),('The missed deadlines were a symptom of poor coordination.','错过截止日期是协调不佳的表现。'),sources=['https://www.etymonline.com/word/symptomatic','https://www.oxfordlearnersdictionaries.com/definition/english/symptom','https://en.wiktionary.org/wiki/symptom#English']),
E('symptomatic','/ˌsɪmptəˈmætɪk/','有症状的；表现出某问题的；针对症状的','既可以说人已经出现症状，也可以说一件事暴露了更深的问题。','借法语 symptomatique 或相关拉丁 symptomaticus，接 symptomat-；现代可对应 symptom 与 -atic，但历史已有完整古典形容词线。',PTO+[['希腊 symptoma、词干 symptomat- → 相关拉丁 symptomaticus；法语 symptomatique','疾病表现相关的形容词线'],['法语或拉丁路线 → 英语 symptomatic','症状相关的；有症状的；表明某种状况的']],'symptomatic patients 是有症状的患者；be symptomatic of something 是某问题的表现。symptomatic treatment 指对症处理，强调针对症状，不自动表示根本原因已被解决。','symptomatic patients；be symptomatic of；symptomatic relief。','symptomatic 与 asymptomatic 分别是有症状和无症状；symptomatic of 后接所反映的问题，不是说前者必然造成后者。',('The study compared symptomatic and asymptomatic participants.','研究比较了有症状和无症状的参与者。'),('The repeated delays are symptomatic of a deeper management problem.','反复延误反映了更深层的管理问题。'),sources=['https://www.etymonline.com/word/symptomatic','https://www.oxfordlearnersdictionaries.com/definition/english/symptomatic','https://en.wiktionary.org/wiki/symptomatic#English']),
E('symptomless','/ˈsɪmptəmlɪs/','无症状的','所讨论的状态没有表现出症状；这是对表现的描述，不自动等于身体毫无问题。','symptom + -less 无、没有；现代英语直接形成否定形容词，与希腊来源前缀构成的 asymptomatic 意思相近。',SYM+[['英语 symptom + -less → symptomless','没有症状的状态']],'remain symptomless 是一直没有症状；a symptomless infection 是没有表现出症状的感染。使用时要看是在说哪种病况、哪个观察阶段。','remain symptomless；a symptomless infection；symptomless cases。','asymptomatic 更常见于正式医学表达；symptomless 构形更透明。healthy 的判断比没有症状更广，两词不能直接等同。',('Some participants remained symptomless throughout the study.','有些参与者在整个研究期间都没有出现症状。'),('The screening programme identified several symptomless cases.','筛查项目发现了几个无症状病例。'),sources=['https://www.collinsdictionary.com/dictionary/english/symptomless','https://en.wiktionary.org/wiki/symptomless#English']),
E('apoptosis','美 /ˌæpəpˈtoʊsəs/，也读 /ˌæpəˈtoʊsəs/','细胞凋亡','像细胞按一套内部步骤有序退场，帮助组织清除不再需要或异常的细胞。','希腊 apoptosis 脱落，apo- 离开 + 与 piptein 落下相关的 ptosis；1972 年研究者用这个脱落意象命名一种受调控的细胞死亡过程。',PTO+[['希腊 apo- + ptosis → apoptosis 脱落','如花瓣、叶片掉落的旧词意象'],['1972 年现代生物学重新使用 apoptosis → 细胞凋亡','将有序细胞删除与其他死亡方式区分']],'undergo apoptosis 是发生凋亡；induce apoptosis 是诱导凋亡。它是一种程序性细胞死亡方式，不应把所有受调控的细胞死亡形式都当成同一个过程。','undergo apoptosis；induce apoptosis；cellular apoptosis。','cell death 是总称；apoptosis 是其中具有特定过程和形态特点的一类。这里的有序退场是帮助理解的比喻，不表示细胞有人的意愿。',('The damaged cells underwent apoptosis.','受损细胞发生了凋亡。'),('Apoptosis helps shape tissues during development.','细胞凋亡帮助组织在发育中形成适当形态。'),sources=['https://www.merriam-webster.com/dictionary/apoptosis','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/apoptosis','https://www.nature.com/articles/bjc197233','https://www.nature.com/articles/s41416-022-02020-0']),
]
