def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED]+list(extra)))
def rootexclude(i):
 r=CATALOG[ASSIGN['roots'][i]['id']];allwords=set(r['family'])|set(r['words'])|set(r['unmatched'])|set(ASSIGN['roots'][i]['family'])
